import type { HarnessReport, ModelReport, ShellReport } from "./parse.ts"

export interface LedgerReports {
  model: ModelReport
  shell: ShellReport
  harness: HarnessReport
}

const markdownCell = (value: string): string => value.replaceAll("|", "\\|")

export const renderLedger = ({ model, shell, harness }: LedgerReports): string => {
  const lines: Array<string> = [
    "<!-- GENERATED BY experiments/entity-store-ledger/src/generate.ts; DO NOT EDIT. -->",
    "",
    "# Entity-store mechanical ledger",
    "",
    "## Model",
    "",
    `Gate constant count: ${model.constantCount}`,
    "",
    "| theorem | axioms |",
    "| --- | --- |"
  ]

  for (const theorem of model.theorems) {
    const axioms = theorem.axioms.length === 0 ? "none" : theorem.axioms.join(", ")
    lines.push(`| ${markdownCell(theorem.theorem)} | ${markdownCell(axioms)} |`)
  }

  lines.push(
    "",
    "## Live build",
    "",
    "### Shell gate",
    "",
    "```text",
    shell.gateLine,
    "```",
    "",
    "### IO whitelist",
    ""
  )
  shell.whitelist.forEach((name, index) => lines.push(`${index + 1}. \`${name}\``))

  lines.push(
    "",
    "### Harness",
    "",
    "| script | status | transcript lines |",
    "| --- | --- | ---: |"
  )
  const scripts = [...harness.scripts].sort((left, right) =>
    left.script < right.script ? -1 : left.script > right.script ? 1 : 0
  )
  for (const result of scripts) {
    lines.push(
      `| ${markdownCell(result.script)} | ${result.status} | ${result.transcriptLines} |`
    )
  }

  lines.push(
    "",
    "```text",
    harness.summaryLine,
    "```",
    "",
    "## Extraction basis",
    "",
    "| working directory | command |",
    "| --- | --- |",
    "| `formal/entity-store` | `~/.elan/bin/lake env lean E2/Gates.lean` |",
    "| `experiments/entity-store-shell` | `~/.elan/bin/lake env lean Shell/Gate.lean` |",
    "| `experiments/entity-store-shell` | `~/.elan/bin/lake exe harness harness <tmp-workdir>` |"
  )

  return lines.join("\n") + "\n"
}
